pub trait Specification<T> {
    fn is_satisfied_by(&self, candidate: &T) -> bool;
}
impl<T, F: Fn(&T) -> bool> Specification<T> for F {
    fn is_satisfied_by(&self, candidate: &T) -> bool { self(candidate) }
}

pub struct And<T>(pub Vec<Box<dyn Specification<T> + Send + Sync>>);
impl<T> Specification<T> for And<T> {
    fn is_satisfied_by(&self, c: &T) -> bool {
        self.0.iter().all(|s| s.is_satisfied_by(c))
    }
}

#[derive(Debug, Clone, serde::Serialize)]
pub enum Spec {
    InStock,
    PriceAtMost(u32),
    And(Box<Spec>, Box<Spec>),
    Not(Box<Spec>),
}

impl Spec {
    pub fn is_satisfied_by(&self, p: &Product) -> bool {
        match self {
            Spec::InStock => p.in_stock,
            Spec::PriceAtMost(max) => p.price_cents <= *max,
            Spec::And(l, r) => l.is_satisfied_by(p) && r.is_satisfied_by(p),
            Spec::Not(inner) => !inner.is_satisfied_by(p),
        }
    }
}

